"""Smoke test for PL-03 (risk.risk_report) on the risk.vol_series fake: runs and has the right shape."""

from __future__ import annotations

import json
from collections.abc import Callable
from pathlib import Path
from types import ModuleType

import pytest

from risk import Report, risk_report
from risk import report_pipeline


@pytest.fixture
def fake_vol(
    monkeypatch: pytest.MonkeyPatch, contract_fake: Callable[[str], ModuleType]
) -> None:
    monkeypatch.setattr(report_pipeline, "vol_series", contract_fake("risk.vol_series").vol_series)


@pytest.mark.usefixtures("fake_vol")
def test_risk_report_runs_end_to_end(tmp_path: Path) -> None:
    out = tmp_path / "report.json"
    report = risk_report(tmp_path / "prices.csv", out, window=2)
    assert isinstance(report, Report)
    assert report.path == str(out)
    assert [row["ticker"] for row in report.rows] == ["AAA", "BBB"]
    assert json.loads(out.read_text())["tickers"] == list(report.rows)


@pytest.mark.usefixtures("fake_vol")
def test_risk_report_passes_tickers_through(tmp_path: Path) -> None:
    report = risk_report(str(tmp_path / "prices.csv"), str(tmp_path / "r.json"), tickers=["BBB"])
    assert [row["ticker"] for row in report.rows] == ["BBB"]


@pytest.mark.usefixtures("fake_vol")
def test_risk_report_passes_window_through(tmp_path: Path) -> None:
    with pytest.raises(ValueError, match="window"):
        risk_report(tmp_path / "prices.csv", tmp_path / "r.json", window=1)

